class Solution:
    def minOperations(self, nums: list[int], k: int) -> int:
        return sum(1 for x in nums if x < k)

class Solution {
public:
    int minOperations(vector<int>& nums, int k) {
        int ans = 0;
        for (int x : nums) {
            if (x < k) ans++;
        }
        return ans;
    }
};

class Solution {
    public int minOperations(int[] nums, int k) {
        int ans = 0;
        for (int x : nums) {
            if (x < k) ans++;
        }
        return ans;
    }
}

var minOperations = function(nums, k) {
    let ans = 0;
    for (const x of nums) {
        if (x < k) ans++;
    }
    return ans;
};
